SINA_SMART["physio1-thyroid"] = {"lecture":"physio1-thyroid","title":"Thyroid physiology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-thyroid:e0","text":"T4 is the main product; T3 is 3-5× more potent; rT3 inactive.","topic":"Hormones and synthesis","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e1","text":"Steps: NIS uptake → TPO oxidation → organification of Tg → coupling → storage → release.","topic":"Hormones and synthesis","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e2","text":"MIT + DIT → T3; DIT + DIT → T4.","topic":"Hormones and synthesis","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e3","text":"Wolff-Chaikoff: excess iodide blocks organification (then escape).","topic":"Hormones and synthesis","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e4","text":"Mostly bound to TBG; only free hormone is active.","topic":"Transport and activation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e5","text":"Deiodinases (selenium): D1, D2 activate; D3 inactivates.","topic":"Transport and activation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e6","text":"TRH (Gq) → TSH (GPCR, cAMP) → all steps + growth (goitre).","topic":"The hypothalamic-pituitary-thyroid axis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e7","text":"Feedback mainly by T3 made by D2 in pituitary; TSH is the best test.","topic":"The hypothalamic-pituitary-thyroid axis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e8","text":"Effects: ↑ BMR, catabolism, ↑ heart rate via β-receptors, brain and bone development.","topic":"Effects and mechanism","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-thyroid:e9","text":"Graves: stimulating TSH-receptor antibodies. Hashimoto: anti-TPO; high TSH.","topic":"Hyper- and hypothyroidism","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"i1oihb":"a","1drjjky":"a","113audv":"a","1ujj33m":"a","207e34":"a","1vy7671":"a","dro2nh":"a","xg2n8d":"a","usdrev":"a","1ccgs4a":"a","sxu0d4":"a","nxsjk":"a","12vjj1r":"a","1tvcu1l":"a","1qej3qu":"a","1n1ffvc":"a","12rovr":"a","18szqgu":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-thyroid:e0":{"s":0,"u":["T4 is the main product; T3 is 3-5× more potent; rT3 inactive.","Thyroid hormones are tyrosine derivatives: T4 (thyroxine, the main secreted form), T3 (3-5 times more potent: higher receptor affinity) and reverse T3 (inactive)."],"dp":[]},"physio1-thyroid:e1":{"s":0,"u":["Steps: NIS uptake → TPO oxidation → organification of Tg → coupling → storage → release.","(4) Coupling by TPO: MIT + DIT → T3; DIT + DIT → T4.","(5) Storage in colloid (2-3 months' supply)."],"dp":[]},"physio1-thyroid:e2":{"s":0,"u":["MIT + DIT → T3; DIT + DIT → T4.","(4) Coupling by TPO: MIT + DIT → T3; DIT + DIT → T4.","(3) Organification : iodine is attached to tyrosines of thyroglobulin (Tg), forming MIT and DIT."],"dp":[]},"physio1-thyroid:e3":{"s":0,"u":["Wolff-Chaikoff: excess iodide blocks organification (then escape).","Very high iodide acutely blocks organification: the Wolff-Chaikoff effect ."],"dp":[]},"physio1-thyroid:e4":{"s":1,"u":["Mostly bound to TBG; only free hormone is active.","Only free hormone is active; T4 half-life is 6-7 days.","A rise in TBG (e.g. pregnancy) transiently lowers free T4, TSH rises, and a new steady state is reached with high total but normal free hormone: the patient is euthyroid."],"dp":[]},"physio1-thyroid:e5":{"s":1,"u":["Deiodinases (selenium): D1, D2 activate; D3 inactivates.","Deiodinases (contain selenocysteine ): D1 (liver, kidney, thyroid) makes T3 and rT3; D2 (brain, pituitary, brown fat) makes local T3 and mediates feedback on TSH and TRH; D3 (brain, placenta, fetus) inactivates T4 and T3."],"dp":[]},"physio1-thyroid:e6":{"s":2,"u":["TRH (Gq) → TSH (GPCR, cAMP) → all steps + growth (goitre).","It acts on a GPCR (cAMP, PLC) and stimulates every step: NIS, TPO and Tg expression, hormone release, blood flow and gland growth; chronic excess causes goitre .","TRH , a tripeptide from the paraventricular nucleus, acts on thyrotrophs through a Gq receptor (PLC, IP₃, Ca²⁺) to release TSH ."],"dp":[]},"physio1-thyroid:e7":{"s":2,"u":["Feedback mainly by T3 made by D2 in pituitary; TSH is the best test.","Negative feedback is mostly by T3 made locally by D2 in the pituitary and hypothalamus.","Because TSH changes steeply with small changes in free T4, TSH is the best single test of thyroid function ."],"dp":[]},"physio1-thyroid:e8":{"s":3,"u":["Effects: ↑ BMR, catabolism, ↑ heart rate via β-receptors, brain and bone development.","Effects: ↑ basal metabolic rate and heat production (UCPs, more mitochondria, Na⁺/K⁺ ATPase) except in brain, testes, uterus, spleen, lymph nodes and anterior pituitary; catabolism (lipolysis, protein breakdown, glycogenolysis, faster glucose absorption); heart : ↑ rate and contractility (more β-receptors, catecholamine sensitivity) with ↓ peripheral resistance; ↑ LDL receptors (lower cholesterol); normal bone growth and brain maturation ."],"dp":[]},"physio1-thyroid:e9":{"s":4,"u":["Graves: stimulating TSH-receptor antibodies. Hashimoto: anti-TPO; high TSH.","Primary (↓ T4, ↑ TSH), the common form: Hashimoto's thyroiditis (anti-TPO and anti-thyroglobulin antibodies) and iodine deficiency , where high TSH produces a painless goitre .","Primary (↑ T4, ↓ TSH): most often Graves' disease , where thyroid-stimulating immunoglobulins activate the TSH receptor, with diffuse goitre."],"dp":[]}},"meta":{"i1oihb":{"a":"recall","vg":"physio1-thyroid:e3/recall/1"},"1drjjky":{"a":"recall","vg":"physio1-thyroid:e3/recall/2"},"113audv":{"a":"recall","vg":"physio1-thyroid:e2/recall/1"},"1ujj33m":{"a":"recall","vg":"physio1-thyroid:e0/recall/1"},"207e34":{"a":"recall","vg":"physio1-thyroid:e4/recall/1"},"1vy7671":{"a":"recall","vg":"physio1-thyroid:e4/recall/2"},"dro2nh":{"a":"recall","vg":"physio1-thyroid:e5/recall/1"},"xg2n8d":{"a":"recall","vg":"physio1-thyroid:e5/recall/2"},"usdrev":{"a":"recall","vg":"physio1-thyroid:e6/recall/1"},"1ccgs4a":{"a":"recall","vg":"physio1-thyroid:e7/recall/1"},"sxu0d4":{"a":"recall","vg":"physio1-thyroid:e3/recall/3"},"nxsjk":{"a":"relationship","vg":"physio1-thyroid:e9/relationship/1"},"12vjj1r":{"a":"recall","vg":"physio1-thyroid:e9/recall/1"},"1tvcu1l":{"a":"recall","vg":"physio1-thyroid:e8/recall/1"},"1qej3qu":{"a":"recall","vg":"physio1-thyroid:e9/recall/2"},"1n1ffvc":{"a":"recall","vg":"physio1-thyroid:e5/recall/3"},"12rovr":{"a":"recall","vg":"physio1-thyroid:e9/recall/3"}},"explRev":"c1d19c8d0439"};
